def dependency_order(n, edges):
    outgoing = [[] for _ in range(n)]
    degree = [0] * n
    for source, target in edges:
        outgoing[source].append(target)
        degree[source] += 1
    queue = [node for node in range(n) if degree[node] == 0]
    order = []
    for node in queue:
        order.append(node)
        for target in outgoing[node]:
            degree[target] -= 1
            if degree[target] == 0:
                queue.append(target)
    return order

