def minimum_coins(coins, amount):
    unreachable = amount + 1
    counts = [0] + [unreachable] * amount
    for subtotal in range(1, amount + 1):
        for coin in coins:
            if coin <= subtotal:
                counts[subtotal] = min(counts[subtotal], counts[subtotal - coin])
    return -1 if counts[amount] == unreachable else counts[amount]

